<script setup>
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '../../app/stores/auth.store'; import { projectsService } from './projects.service'; import { stagesService } from './stages.service'; import { usersService } from './users.service'; import { tasksService } from '../tasks/tasks.service'; import { projectPayload, runAdminMutation, taskPayload } from '../../app/services/admin-ui'; import AsyncState from '../../shared/components/AsyncState.vue'; import Badges from '../../shared/components/Badges.vue'; import TaskCard from '../../shared/components/TaskCard.vue'; import BaseModal from '../../shared/components/BaseModal.vue'; import ProjectForm from './ProjectForm.vue'; import StageForm from './StageForm.vue'; import TaskForm from '../tasks/TaskForm.vue'; import ProjectMembersPanel from './ProjectMembersPanel.vue'; import StageMembersPanel from './StageMembersPanel.vue'
const props = defineProps({ projectId: String }); const auth = useAuthStore(); const project = ref(null); const stages = ref([]); const tasks = ref([]); const members = ref([]); const users = ref([]); const stageMembers = ref({}); const loading = ref(true); const error = ref(''); const activeTab = ref('board'); const busy = ref(false); const editProject = ref(false); const stageModal = ref(null); const taskModal = ref(null)
const canManage = computed(() => auth.isAdmin); const editable = computed(() => ['Active', 'Paused'].includes(project.value?.status)); const tabs = computed(() => canManage.value ? [{ id: 'board', label: 'Tablero' }, { id: 'members', label: 'Miembros' }, { id: 'settings', label: 'Configuración' }] : [{ id: 'board', label: 'Tablero' }, { id: 'members', label: 'Miembros' }])
const stageTasks = id => tasks.value.filter(task => task.stageId === id); const stageMemberList = stage => stageMembers.value[stage.id] || []
async function load() { loading.value = true; try { const values = await Promise.all([projectsService.get(props.projectId), projectsService.stages(props.projectId), projectsService.tasks(props.projectId), projectsService.members(props.projectId), canManage.value ? usersService.list() : Promise.resolve([])]); [project.value, stages.value, tasks.value, members.value, users.value] = values; if (canManage.value) { const pairs = await Promise.all(stages.value.map(async stage => [stage.id, await stagesService.members(props.projectId, stage.id)])); stageMembers.value = Object.fromEntries(pairs) } } catch (e) { error.value = e.message } finally { loading.value = false } }
async function mutate(operation) { busy.value = true; const ok = await runAdminMutation(operation, load, message => error.value = message); busy.value = false; return ok }
async function saveProject(form) { if (await mutate(() => projectsService.update(project.value.id, { ...projectPayload(form), version: project.value.version }))) editProject.value = false }
async function lifecycle(action, terminal = false) { if (terminal && !window.confirm(`¿${action === 'complete' ? 'Completar' : 'Cancelar'} este proyecto?`)) return; await mutate(() => projectsService.lifecycle(project.value.id, action, project.value.version)) }
async function saveStage(form) { const current = stageModal.value; const operation = current?.stage ? () => stagesService.update(project.value.id, current.stage.id, { ...form, version: current.stage.version }) : () => stagesService.create(project.value.id, form); if (await mutate(operation)) stageModal.value = null }
async function reorder(stage, direction) { const index = stages.value.findIndex(item => item.id === stage.id); const target = index + direction; if (target < 0 || target >= stages.value.length) return; const ordered = [...stages.value]; [ordered[index], ordered[target]] = [ordered[target], ordered[index]]; await mutate(() => stagesService.reorder(project.value.id, ordered.map((item, position) => ({ stageId: item.id, position: position + 1, version: item.version })))) }
async function saveTask(form) { const stage = taskModal.value; if (await mutate(() => tasksService.create(project.value.id, { ...taskPayload(form), stageId: stage.id, assigneeIds: [] }))) taskModal.value = null }
async function removeMember(member) { if (!window.confirm(`¿Quitar a ${member.fullName} del proyecto?`)) return; await mutate(() => projectsService.removeMember(project.value.id, member.userId)) }
async function addStageMember(stage, userId, role) { await mutate(() => stagesService.addMember(project.value.id, stage.id, userId, role)) }
async function removeStageMember(stage, member) { await mutate(() => stagesService.removeMember(project.value.id, stage.id, member.userId)) }
onMounted(load)
</script>
<template><section class="page"><AsyncState :loading="loading" :error="error" :empty="false"><header class="page-header board-header"><div><RouterLink to="/projects" class="back-link">← Proyectos</RouterLink><div class="title-line"><h1>{{ project.name }}</h1><Badges :value="project.status" /></div><p>{{ project.description || 'Sin descripción del proyecto.' }}</p><p class="project-dates">{{ project.startDate || 'Sin inicio' }} — {{ project.endDate || 'Sin fin' }}</p></div><div v-if="canManage" class="action-row"><button class="button secondary" :disabled="busy || !editable" @click="editProject = true">Editar</button><button v-if="project.status === 'Active'" class="button secondary" :disabled="busy" @click="lifecycle('pause')">Pausar</button><button v-if="project.status === 'Paused'" class="button secondary" :disabled="busy" @click="lifecycle('resume')">Reanudar</button><button v-if="editable" class="button secondary" :disabled="busy" @click="lifecycle('complete', true)">Completar</button><button v-if="editable" class="button danger-button" :disabled="busy" @click="lifecycle('cancel', true)">Cancelar</button></div></header><p v-if="error" class="form-error">{{ error }}</p><nav class="local-tabs"><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ tab.label }}</button></nav><div v-if="activeTab === 'board'"><div class="board-actions" v-if="canManage && editable"><button class="button secondary" @click="stageModal = {}">+ Agregar etapa</button></div><div v-if="!stages.length" class="state-card"><b>Este proyecto todavía no tiene etapas.</b><span>Organiza el flujo de trabajo antes de añadir tareas.</span><button v-if="canManage && editable" class="button primary" @click="stageModal = {}">Crear primera etapa</button></div><div v-else class="board"><section v-for="(stage, index) in stages" :key="stage.id" class="board-column" :class="{ inactive: !stage.isActive }"><header><div><span class="stage-index">{{ String(stage.position).padStart(2, '0') }}</span><h2>{{ stage.name }}</h2></div><span>{{ stageTasks(stage.id).length }}</span></header><p v-if="stage.description">{{ stage.description }}</p><div v-if="canManage" class="stage-actions"><button class="text-button" :disabled="busy || !editable" @click="stageModal = { stage }">Editar</button><button class="text-button" :disabled="busy || !editable || index === 0" @click="reorder(stage, -1)">←</button><button class="text-button" :disabled="busy || !editable || index === stages.length - 1" @click="reorder(stage, 1)">→</button><button class="text-button" :disabled="busy || !editable" @click="mutate(() => stagesService.toggle(project.id, stage.id, stage.isActive ? 'deactivate' : 'activate', stage.version))">{{ stage.isActive ? 'Desactivar' : 'Activar' }}</button></div><button v-if="canManage && editable && stage.isActive" class="new-task" @click="taskModal = stage">+ Nueva tarea</button><div class="task-stack"><TaskCard v-for="task in stageTasks(stage.id)" :key="task.id" :task="task" /><div v-if="!stageTasks(stage.id).length" class="column-empty">No hay tareas en esta etapa.</div></div></section></div></div><ProjectMembersPanel v-else-if="activeTab === 'members'" :members="members" :users="users" :can-manage="canManage" :submitting="busy" @add="userId => mutate(() => projectsService.addMember(project.id, userId))" @remove="removeMember" /><section v-else class="config-panel"><header><div><p class="eyebrow">FLUJO</p><h2>Configuración de etapas</h2><p>Define quién participa en cada parte del proceso.</p></div></header><StageMembersPanel v-for="stage in stages" :key="stage.id" :stage="stage" :members="stageMemberList(stage)" :project-members="members" :can-manage="canManage" :submitting="busy" @add="addStageMember" @remove="removeStageMember" /></section><BaseModal v-model="editProject" title="Editar proyecto"><ProjectForm :project="project" :submitting="busy" @submit="saveProject" /></BaseModal><BaseModal :model-value="Boolean(stageModal)" :title="stageModal?.stage ? 'Editar etapa' : 'Nueva etapa'" @update:model-value="value => { if (!value) stageModal = null }"><StageForm :stage="stageModal?.stage" :submitting="busy" @submit="saveStage" /></BaseModal><BaseModal :model-value="Boolean(taskModal)" title="Nueva tarea" @update:model-value="value => { if (!value) taskModal = null }"><TaskForm :submitting="busy" @submit="saveTask" /></BaseModal></AsyncState></section></template>
